import{_ as i,c as t,o as e,ag as a}from"./chunks/framework.Bzez9NG9.js";const n="/space/img/python-git-start.png",o="/space/img/python-git-integration.png",y=JSON.parse('{"title":"Git","description":"Manage Git repositories in SPACE Python and configure SSH access for client-managed SPACE installations.","frontmatter":{"title":"Git","description":"Manage Git repositories in SPACE Python and configure SSH access for client-managed SPACE installations.","keywords":["Git","source control","SSH","Python","notebooks"],"outline":"deep"},"headers":[],"relativePath":"doc/python/git.md","filePath":"doc/python/git.md"}'),p={name:"doc/python/git.md"};function h(r,s,l,d,c,k){return e(),t("div",null,s[0]||(s[0]=[a('<h1 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h1><p>SPACE provides integrated Git version control for Python scripts, notebooks, and other project files. You can clone repositories, track changes, commit updates, and synchronize with remote repositories directly from <strong>SPACE Python</strong>.</p><p>Git is separate from the <a href="./../planning-analytics/git.html">Planning Analytics Git integration</a>, which manages IBM Planning Analytics model assets.</p><p>SPACE works with Git repositories accessible over SSH, including repositories hosted on GitHub, GitLab, Bitbucket, Azure DevOps, and self-hosted Git servers. GitHub has been tested; compatibility with other providers depends on their SSH configuration.</p><h2 id="working-with-git" tabindex="-1">Working with Git <a class="header-anchor" href="#working-with-git" aria-label="Permalink to &quot;Working with Git&quot;">​</a></h2><p>Open <strong>SPACE Python</strong>. The <strong>File Browser</strong> displays the shared Python workspace (<code>/jupyter</code>), and the <strong>Git</strong> icon in the left sidebar opens the Git interface.</p><h3 id="clone-or-initialize-a-repository" tabindex="-1">Clone or initialize a repository <a class="header-anchor" href="#clone-or-initialize-a-repository" aria-label="Permalink to &quot;Clone or initialize a repository&quot;">​</a></h3><p><img src="'+n+'" alt="Git sidebar with options to initialize or clone a repository" data-zoomable=""></p><p><strong>To clone an existing repository:</strong></p><ol><li><p>Open the <strong>File Browser</strong> and navigate to the location where you want to keep the repository, usually the workspace root (<code>/jupyter</code>).</p></li><li><p>Open the <strong>Git</strong> tab in the left sidebar and select <strong>Clone a Repository</strong>.</p></li><li><p>Enter the repository&#39;s SSH URL, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git@github.com:organization/repository.git</span></span></code></pre></div></li><li><p>Complete the clone operation, then open the cloned repository folder in the File Browser.</p></li></ol><p>A single shared repository is a good starting point. <code>/jupyter/git</code> is a suggested repository location, but you can choose another folder.</p><p><strong>To start a new repository:</strong> Create and open a dedicated project folder, select the <strong>Git</strong> tab, and choose <strong>Initialize a Repository</strong>. Avoid initializing a repository at the <code>/jupyter</code> workspace root unless you intentionally want to version the entire workspace.</p><h3 id="review-commit-pull-and-push" tabindex="-1">Review, commit, pull, and push <a class="header-anchor" href="#review-commit-pull-and-push" aria-label="Permalink to &quot;Review, commit, pull, and push&quot;">​</a></h3><p>When you open a folder within a Git repository, the Git sidebar shows its changes, commit history, and branches.</p><p><img src="'+o+`" alt="Git sidebar showing changed files, commit controls, history, and branches" data-zoomable=""></p><ul><li><strong>Review changes:</strong> Check the <strong>Changed</strong> and <strong>Untracked</strong> sections for modified or newly created files.</li><li><strong>Commit:</strong> Stage the files you want to include, enter a commit message, and select <strong>Commit</strong>.</li><li><strong>Pull:</strong> Use the pull action in the Git toolbar to retrieve and integrate remote changes.</li><li><strong>Push:</strong> Use the push action to publish your local commits to the remote repository.</li><li><strong>Branches and history:</strong> Use <strong>Branches and Tags</strong> and <strong>History</strong> to work with branches and review previous commits.</li></ul><p>A commit is saved locally; <strong>it is not uploaded to the remote repository until you push it</strong>.</p><p>You can add a <code>.gitignore</code> file to a repository to exclude temporary files, notebook checkpoints (such as <code>.ipynb_checkpoints/</code>), and other files that should not be tracked by Git.</p><p>The Python workspace is shared, so users working in the same repository should coordinate changes to avoid conflicts.</p><h2 id="git-authentication" tabindex="-1">Git authentication <a class="header-anchor" href="#git-authentication" aria-label="Permalink to &quot;Git authentication&quot;">​</a></h2><p>Git access is configured <strong>once per SPACE installation</strong>, rather than separately for each SPACE user. Users share the remote repository permissions granted to the configured SSH key.</p><ul><li><strong>Succeedium-managed installations:</strong> Succeedium configures Git and provides the SSH public key. Your Git administrator registers the key with the repository or Git provider.</li><li><strong>Client-managed installations:</strong> A server administrator configures SSH access using the instructions below.</li></ul><p>A <strong>read-only</strong> key allows users to clone, fetch, and pull, and they can still make local commits. <strong>Write access</strong> is required to push commits to the remote repository, subject to any branch protection or other Git provider restrictions.</p><h2 id="client-managed-configuration" tabindex="-1">Client-managed configuration <a class="header-anchor" href="#client-managed-configuration" aria-label="Permalink to &quot;Client-managed configuration&quot;">​</a></h2><p>Standard SPACE installations include two configuration templates in <code>config/python/git/</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.gitconfig.example</span></span>
<span class="line"><span>ssh_config.example</span></span></code></pre></div><p>The Git configuration directory is already mounted in the SPACE Python service. No Docker Compose changes are required for a standard installation.</p><h3 id="_1-prepare-the-configuration-files" tabindex="-1">1. Prepare the configuration files <a class="header-anchor" href="#_1-prepare-the-configuration-files" aria-label="Permalink to &quot;1. Prepare the configuration files&quot;">​</a></h3><p>From your SPACE installation directory, create the active configuration files from the templates:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git/.gitconfig.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git/.gitconfig</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git/ssh_config.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git/ssh_config</span></span></code></pre></div><p>Edit <code>.gitconfig</code> to specify the default commit identity, for example:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[user]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = SPACE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    email</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = space@example.com</span></span></code></pre></div><p>Use a name and email appropriate for your organization. This is the default identity for commits made through SPACE.</p><p>Edit <code>ssh_config</code> for your Git provider. For GitHub, use:</p><div class="language-ssh-config vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ssh-config</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Host</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> github.com</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    HostName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> github.com</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> git</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    IdentityFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /space-git/space_git_key</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    IdentitiesOnly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> yes</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    UserKnownHostsFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /space-git/known_hosts</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    StrictHostKeyChecking</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> yes</span></span></code></pre></div><p>For another provider, update the host settings and use the SSH repository URL supplied by that provider.</p><h3 id="_2-generate-and-register-an-ssh-key" tabindex="-1">2. Generate and register an SSH key <a class="header-anchor" href="#_2-generate-and-register-an-ssh-key" aria-label="Permalink to &quot;2. Generate and register an SSH key&quot;">​</a></h3><p>Generate a dedicated Ed25519 key pair on the SPACE server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git/space_git_key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;SPACE Git&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span></span></code></pre></div><p>This creates <code>space_git_key</code> (private key) and <code>space_git_key.pub</code> (public key). The empty passphrase supports unattended Git operations; keep the private key protected as described below.</p><p>Display the public key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git/space_git_key.pub</span></span></code></pre></div><p>Register the public key with your Git provider. For <strong>GitHub</strong>, open the repository&#39;s <strong>Settings → Deploy keys → Add deploy key</strong>, paste the public key, and enable <strong>Allow write access</strong> if SPACE users need to push changes. For other providers, follow their corresponding SSH key setup procedure.</p><p>Grant only the permissions required for the repository.</p><h3 id="_3-configure-trusted-ssh-hosts" tabindex="-1">3. Configure trusted SSH hosts <a class="header-anchor" href="#_3-configure-trusted-ssh-hosts" aria-label="Permalink to &quot;3. Configure trusted SSH hosts&quot;">​</a></h3><p>Retrieve the Git provider&#39;s SSH host key and check its fingerprint against the fingerprint published in the provider&#39;s official documentation <strong>before trusting it</strong>.</p><p>For GitHub:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tmp_file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mktemp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keyscan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$tmp_file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$tmp_file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Compare the displayed fingerprint with <a href="https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/githubs-ssh-key-fingerprints" target="_blank" rel="noreferrer">GitHub&#39;s published SSH key fingerprints</a>.</p><p><strong>If the fingerprints do not match, do not save or trust the host key. Investigate the mismatch before continuing.</strong></p><p>Once verified, save the key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$tmp_file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git/known_hosts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$tmp_file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>For other providers, use their hostname and officially verified host key.</p><p>After setup, the configuration directory should contain:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config/python/git/</span></span>
<span class="line"><span>├── .gitconfig.example</span></span>
<span class="line"><span>├── ssh_config.example</span></span>
<span class="line"><span>├── .gitconfig</span></span>
<span class="line"><span>├── ssh_config</span></span>
<span class="line"><span>├── space_git_key</span></span>
<span class="line"><span>├── space_git_key.pub</span></span>
<span class="line"><span>└── known_hosts</span></span></code></pre></div><h3 id="_4-secure-the-configuration" tabindex="-1">4. Secure the configuration <a class="header-anchor" href="#_4-secure-the-configuration" aria-label="Permalink to &quot;4. Secure the configuration&quot;">​</a></h3><p>Apply restricted ownership and permissions to the directory and all files:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root:root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 700</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/python/git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span></span></code></pre></div><p>Repeat these commands after adding or replacing configuration files. Never store the private SSH key in the shared Python workspace or commit it to a repository.</p><h3 id="_5-apply-and-verify" tabindex="-1">5. Apply and verify <a class="header-anchor" href="#_5-apply-and-verify" aria-label="Permalink to &quot;5. Apply and verify&quot;">​</a></h3><p>Restart the SPACE Python service to load the Git configuration. For the standard Docker Compose installation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./config/secrets.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-deps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> space-python</span></span></code></pre></div><p>Open <strong>SPACE Python</strong>, clone the repository using its SSH URL, make a test commit, and push it if the key has write access. If authentication fails, check the public-key registration, SSH host configuration, and repository permissions.</p>`,63)]))}const u=i(p,[["render",h]]);export{y as __pageData,u as default};
